BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='2s';
SELECT jsonb_build_object(
 'table',(SELECT jsonb_build_object('rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),'partition',c.relispartition,'kind',c.relkind) FROM pg_class c WHERE c.oid=to_regclass('public.artifacts')),
 'defaults',(SELECT coalesce(jsonb_agg(jsonb_build_object('column',a.attname,'expression',CASE WHEN pg_get_expr(d.adbin,d.adrelid) IN('gen_random_uuid()','now()','true','false') THEN pg_get_expr(d.adbin,d.adrelid) ELSE '[LITERAL_REDACTED]' END,'md5',md5(pg_get_expr(d.adbin,d.adrelid))) ORDER BY a.attnum),'[]'::jsonb) FROM pg_attribute a JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=to_regclass('public.artifacts') AND a.attnum>0 AND NOT a.attisdropped),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),'unique',i.indisunique,'primary',i.indisprimary,'valid',i.indisvalid,'ready',i.indisready) ORDER BY ic.relname),'[]'::jsonb) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=to_regclass('public.artifacts')),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'internal',t.tgisinternal,'enabled',t.tgenabled,'type',t.tgtype,'function_schema',pn.nspname,'function_name',p.proname,'args_md5',md5(t.tgargs::text),'definition_when_md5',md5(t.tgqual::text),'referenced_table',rc.relname) ORDER BY t.tgname),'[]'::jsonb) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace LEFT JOIN pg_class rc ON rc.oid=t.tgconstrrelid WHERE t.tgrelid=to_regclass('public.artifacts')),
 'inheritance',(SELECT coalesce(jsonb_agg(jsonb_build_object('child',c.relname,'parent',p.relname)),'[]'::jsonb) FROM pg_inherits i JOIN pg_class c ON c.oid=i.inhrelid JOIN pg_class p ON p.oid=i.inhparent WHERE i.inhrelid=to_regclass('public.artifacts') OR i.inhparent=to_regclass('public.artifacts')),
 'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee,a.privilege_type),'[]'::jsonb) FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=to_regclass('public.artifacts')),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypass_rls',rolbypassrls,'inherit',rolinherit,'login',rolcanlogin) ORDER BY rolname) FROM pg_roles WHERE rolname IN('anon','authenticated','service_role')),
 'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('member',r.rolname,'granted_role',g.rolname,'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option) ORDER BY r.rolname,g.rolname),'[]'::jsonb) FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.member JOIN pg_roles g ON g.oid=m.roleid WHERE r.rolname IN('anon','authenticated','service_role')),
 'schema',(SELECT jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'browser_create',has_schema_privilege('anon',n.oid,'CREATE') OR has_schema_privilege('authenticated',n.oid,'CREATE'),'service_usage',has_schema_privilege('service_role',n.oid,'USAGE')) FROM pg_namespace n WHERE n.nspname='public')
) AS metadata;
COMMIT;
